() => {
  const inputs = document.querySelectorAll('input');
  return Array.from(inputs).map(i => ({type: i.type, placeholder: i.placeholder, id: i.id, name: i.name}));
}

() => {
  const setNativeValue = (el, value) => {
    const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const desc = Object.getOwnPropertyDescriptor(proto, 'value');
    desc.set.call(el, value);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  const inputs = document.querySelectorAll('input');
  setNativeValue(inputs[0], 'admin');
  setNativeValue(inputs[1], 'admin123');
  const btn = document.querySelector('button');
  return { values: [inputs[0].value, inputs[1].value], btnDisabled: btn ? btn.disabled : null, btnText: btn ? btn.textContent : null };
}

