async () => {
  const token = JSON.parse(localStorage.getItem('auth-store') || '{}').state.token;
  const res = await fetch('/api/knowledge', { headers: { Authorization: 'Bearer ' + token } });
  const text = await res.text();
  return { status: res.status, body: text.slice(0, 2000) };
}

async () => {
  const token = JSON.parse(localStorage.getItem('auth-store') || '{}').state.token;
  const res = await fetch('/api/datasources', { headers: { Authorization: 'Bearer ' + token } });
  const data = await res.json();
  const list = Array.isArray(data) ? data : (data.data || data.items || []);
  const out = [];
  for (const ds of list) {
    const r = await fetch('/api/knowledge?dataSourceId=' + encodeURIComponent(ds.id), { headers: { Authorization: 'Bearer ' + token } });
    const kd = await r.json();
    const items = Array.isArray(kd) ? kd : (kd.items || kd.data || []);
    out.push({ id: ds.id, name: ds.name, knowledgeCount: items.length });
  }
  return out;
}

